load_screen_pan1_776511902784:
    ; Load pan1 screen (fast direct port access)
    ; Set VDP colors FIRST (before loading screen data)
    ld a, 1           ; Background color
    ld b, 1       ; Border color
    call set_screen_colors
    ; Initialize character 0 (empty cells) with background color
    ld a, 1           ; Background color for char 0
    call init_char0_color
    ld a, (current_screen2_tilebank_id)
    cp SCREEN2_TILEBANK_TILEBANK_1776511918552_ID
    jr z, .load_pan1_776511902784_tilebank_ready
    call load_tilebank_tilebank_1776511918552_patterns_to_vram
    call load_tilebank_tilebank_1776511918552_colors_to_vram
    ld a, SCREEN2_TILEBANK_TILEBANK_1776511918552_ID
    ld (current_screen2_tilebank_id), a
    xor a
    ld (vram_cache_font_ready), a
    call init_font_system
.load_pan1_776511902784_tilebank_ready:
    ; Clear hardware sprites on screen switch to avoid visual carry-over
    call clear_all_sprites
    call update_sprites_to_vram
    ; Load optimized background block data into RAM scratch buffers and expand it
    ; Decompress ZX0 screen block catalog into runtime_effects_layout
    di
    ld hl, SCREEN_PAN1_0_BLOCK_CATALOG
    ld de, runtime_effects_layout
    call dzx0_standard
    ei
    ld hl, runtime_effects_layout
    ld de, runtime_effects_layout
    ld bc, SCREEN_PAN1_0_BLOCK_CATALOG_SIZE
    ldir
    ; Decompress ZX0 screen block map into runtime_screen_layout
    di
    ld hl, SCREEN_PAN1_0_BLOCK_MAP
    ld de, runtime_screen_layout
    call dzx0_standard
    ei
    ld hl, runtime_screen_layout
    ld de, runtime_screen_layout
    ld bc, SCREEN_PAN1_0_BLOCK_MAP_SIZE
    ldir
    ld hl, runtime_effects_layout
    ld de, runtime_screen_layout
    ld a, SCREEN_PAN1_0_BLOCK_LAYOUT_MODE
    call expand_screen_block_layout_to_background
    ld hl, runtime_background_layout
    ld de, runtime_screen_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir
    ; Decompress ZX0 effects layout directly into runtime_effects_layout
    di
    ld hl, SCREEN_PAN1_0_EFFECTS_LAYOUT
    ld de, runtime_effects_layout
    call dzx0_standard
    ei
    ld hl, runtime_effects_layout
    ld de, runtime_effects_layout
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_PAN1_0_CHAR_BEHAVIOR_TABLE
    ld de, runtime_char_behavior_table
    ld bc, SCREEN_PAN1_0_CHAR_BEHAVIOR_TABLE_SIZE
    ldir

    ld hl, SCREEN_PAN1_0_INTERACTION_TYPE_MAP
    ld de, runtime_interaction_type_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_PAN1_0_INTERACTION_VALUE_MAP
    ld de, runtime_interaction_value_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, SCREEN_PAN1_0_INTERACTION_TARGET_MAP
    ld de, runtime_interaction_target_map
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    ldir

    ld hl, runtime_screen_layout
    call build_runtime_behavior_map_from_screen_layout

    ld a, 0
    ld (current_effect_zone_count), a
    or a
    jr z, .load_pan1_776511902784_zones_done
    ld hl, SCREEN_PAN1_0_EFFECT_ZONE_TABLE
    ld de, runtime_effect_zone_table
    ld bc, 0
    ldir
.load_pan1_776511902784_zones_done:
    ; Now load screen layout (full 32x24) from runtime RAM buffer
    ld hl, runtime_screen_layout
    ld de, NAMETBL
    ld bc, RUNTIME_SCREEN_MAP_SIZE
    call FAST_LDIRVM           ; Fast VRAM write (direct port access)
    ld a, 2
    ld (current_screen_anim_group_count), a
    ld a, 1
    ld (current_screen_entity_count), a
    ld a, 25
    ld (current_screen_sprite_pattern_slots), a
    ld a, SCREEN_PAN1_0_SUMMARY_FLAGS
    ld (current_screen_summary_flags), a
    call update_animated_tiles_vram
    ; Initialize collision system pointers for this screen
    ld hl, runtime_screen_layout
    ld (current_screen_layout), hl
    ld a, #FF
    ld (current_screen_layout_bank), a
    ld hl, runtime_behavior_map
    ld (current_behavior_map), hl
    ld a, #FF
    ld (current_behavior_map_bank), a
    ld a, l
    ld (behavior_cache_map_l), a
    ld a, h
    ld (behavior_cache_map_h), a
    ld a, #FF
    ld (behavior_cache_row), a
    xor a
    ld (secret_zone_active), a
    ld (secret_zone_rect_x), a
    ld (secret_zone_rect_y), a
    ld (secret_zone_rect_w), a
    ld (secret_zone_rect_h), a
    ld hl, entity_button_contact_active
    ld de, entity_button_contact_active + 1
    ld bc, 31
    ld (hl), a
    ldir
    ret


