Action_SetVariable:
; Params: VarID(1 byte), ValueLo(1 byte), ValueHi(1 byte)
; Supports both entity variables (ID 0-5) and global variables (ID 6+)
    ld a, (hl)              ; A = VarID
    inc hl
    ld c, (hl)              ; C = ValueLo
    inc hl
    ld e, (hl)              ; E = ValueHi
    inc hl

    push hl                 ; Save Params Ptr
    push bc                 ; Save ValueLo and Entity Index for the entity-variable path

    ; Check if VarID < 6 (entity variable)
    cp 6
    jr c, .entity_variable

.global_variable:
    ; VarID >= 6: Global variable
    ; Calculate table offset: (VarID - 6) * 2
    sub 6                   ; A = VarID - 6
    ld b, a                 ; B = global variable table index
    ld l, a
    ld h, 0
    add hl, hl              ; HL = (VarID - 6) * 2

    ; Get address from SM_GlobalVarTable
    push de                 ; Preserve ValueHi while resolving the address
    ld de, SM_GlobalVarTable
    add hl, de              ; HL = &SM_GlobalVarTable[VarID - 6]

    ; Read address from table (16-bit)
    ld e, (hl)
    inc hl
    ld d, (hl)
    ex de, hl               ; HL = address of global variable
    pop de                  ; Restore ValueHi in E
    push hl                 ; Preserve target address
    ld a, b
    ld l, a
    ld h, 0
    push de                 ; Preserve ValueHi while checking word flag
    ld de, SM_GlobalVarWordTable
    add hl, de
    ld a, (hl)              ; A = 1 when the target global variable is word-sized
    pop de                  ; E = ValueHi
    pop hl                  ; HL = address of global variable
    or a
    jr z, .store_global_byte

.store_global_word:
    ld (hl), c              ; Store low byte
    inc hl
    ld (hl), e              ; Store high byte
    jr .set_global_sync

.store_global_byte:
    ld (hl), c              ; Store value in byte global variable

.set_global_sync:
    push af
    push bc
    push de
    push hl
    call force_render_hud   ; Keep HUD text synchronized with SM global writes
    pop hl
    pop de
    pop bc
    pop af

    pop bc                  ; Discard saved ValueLo/Entity Index from the entity-variable path
    pop hl                  ; Restore Params Ptr
    ret

.entity_variable:
    ; VarID 0-5: Entity variables (x, y, vx, vy, isOnGround, health)
    ; Map VarID to entity variable address
    push af                 ; Save VarID
    ld c, b                 ; C = Entity Index
    ld b, 0                 ; BC = Entity Index
    pop af                  ; A = VarID

    ; Dispatch based on VarID
    or a
    jr z, .set_x
    dec a
    jr z, .set_y
    dec a
    jr z, .set_vx
    dec a
    jr z, .set_vy
    dec a
    jr z, .set_on_ground
    ; VarID 5 = health

.set_health:
    ld hl, entity_health_current
    add hl, bc
    pop bc                  ; C = ValueLo
    ld (hl), c
    pop hl
    ret

.set_x:
    ld hl, entity_x_pos
    add hl, bc
    pop bc                  ; C = ValueLo
    ld (hl), c
    pop hl
    ret

.set_y:
    ld hl, entity_y_pos
    add hl, bc
    pop bc                  ; C = ValueLo
    ld (hl), c
    pop hl
    ret

.set_vx:
    ld hl, entity_vel_x
    add hl, bc
    pop bc                  ; C = ValueLo
    ld (hl), c
    pop hl
    ret

.set_vy:
    ld hl, entity_vel_y
    add hl, bc
    pop bc                  ; C = ValueLo
    ld (hl), c
    pop hl
    ret

.set_on_ground:
    ld hl, entity_on_ground
    add hl, bc
    pop bc                  ; C = ValueLo
    ld a, c
    or a
    jr z, .clear_ground
    set 0, (hl)             ; Set bit 0
    pop hl
    ret
.clear_ground:
    res 0, (hl)             ; Clear bit 0
    pop hl
    ret

Action_IncVariable:
; Params: VarID(1 byte), AmountLo(1 byte), AmountHi(1 byte)
; Supports both entity variables (ID 0-5) and global variables (ID 6+)
    ld a, (hl)              ; A = VarID
    inc hl
    ld c, (hl)              ; C = AmountLo
    inc hl
    ld e, (hl)              ; E = AmountHi
    inc hl

    push hl                 ; Save Params Ptr

    ; Check if VarID < 6 (entity variable)
    cp 6
    jr nc, .inc_global

.inc_entity:
    ; Entity variable increment (simplified: only supports x, y positions for now)
    push bc                 ; Save Amount and Entity Index
    ld e, b                 ; E = Entity Index
    ld d, 0                 ; DE = Entity Index

    ; Map VarID to address (0=x, 1=y, 2=vx, 3=vy, 5=health)
    or a
    jr z, .inc_entity_x
    dec a
    jr z, .inc_entity_y
    dec a
    jr z, .inc_entity_vx
    dec a
    jr z, .inc_entity_vy
    dec a
    jr z, .inc_entity_on_ground
    jr .inc_entity_health   ; Default to health

.inc_entity_x:
    ld hl, entity_x_pos
    jr .do_inc_entity
.inc_entity_y:
    ld hl, entity_y_pos
    jr .do_inc_entity
.inc_entity_vx:
    ld hl, entity_vel_x
    jr .do_inc_entity
.inc_entity_vy:
    ld hl, entity_vel_y
    jr .do_inc_entity
.inc_entity_on_ground:
    ld hl, entity_on_ground
    jr .do_inc_entity
.inc_entity_health:
    ld hl, entity_health_current

.do_inc_entity:
    add hl, de              ; HL = address of entity variable
    pop bc                  ; C = Amount
    ld a, (hl)
    add a, c
    ld (hl), a
    pop hl                  ; Restore Params Ptr
    ret

.inc_global:
    ; VarID >= 6: Global variable
    sub 6                   ; A = VarID - 6
    ld b, a                 ; B = global variable table index
    ld l, a
    ld h, 0
    add hl, hl              ; HL = (VarID - 6) * 2

    push de                 ; Preserve AmountHi while resolving the address
    ld de, SM_GlobalVarTable
    add hl, de              ; HL = &SM_GlobalVarTable[VarID - 6]

    ; Read address from table
    ld e, (hl)
    inc hl
    ld d, (hl)
    ex de, hl               ; HL = address of global variable
    pop de                  ; Restore AmountHi in E
    push hl                 ; Preserve target address
    ld a, b
    ld l, a
    ld h, 0
    push de                 ; Preserve AmountHi while checking word flag
    ld de, SM_GlobalVarWordTable
    add hl, de
    ld a, (hl)              ; A = 1 when the target global variable is word-sized
    pop de                  ; E = AmountHi
    pop hl                  ; HL = address of global variable
    or a
    jr z, .inc_global_byte

.inc_global_word:
    ld a, (hl)              ; Add low byte
    add a, c
    ld (hl), a
    inc hl
    ld a, (hl)              ; Add high byte + carry
    adc a, e
    ld (hl), a
    jr .inc_global_sync

.inc_global_byte:
    ld a, (hl)              ; Get current value
    add a, c                ; Add amount
    ld (hl), a              ; Store new value

.inc_global_sync:
    push af
    push bc
    push de
    push hl
    call force_render_hud   ; Keep HUD text synchronized with SM global increments
    pop hl
    pop de
    pop bc
    pop af

    pop hl                  ; Restore Params Ptr
    ret

