SM_ConditionTable:
    DW Condition_Nop            ; 0
    DW Condition_And            ; 1
    DW Condition_Nop ; 2 [Condition_Or stripped]
    DW Condition_Nop ; 3 [Condition_Not stripped]
    DW Condition_KeyPressed     ; 4
    DW Condition_KeyReleased    ; 5
    DW Condition_Nop ; 6 [Condition_TimeOut stripped]
    DW Condition_Nop ; 7 [Condition_CanMove stripped]
    DW Condition_Nop ; 8 [Condition_HasCollision stripped]
    DW Condition_Nop ; 9 [Condition_PathClear stripped]
    DW Condition_Nop ; 10 [Condition_OnWallCollision stripped]
    DW Condition_Nop ; 11 [Condition_DeadlyTile stripped]
    DW Condition_Nop ; 12 [Condition_AnimComplete stripped]
    DW Condition_Nop ; 13 [Condition_KeyAndMove stripped]
    DW Condition_VariableCompare; 14
    DW Condition_Nop ; 15 [Condition_Xor stripped]

    ; ------------------------------------------------------------------
    ; CONDITION HANDLERS IMPLEMENTATION
    ; ------------------------------------------------------------------

Condition_Nop:
    ld a, 1                 ; Always true
    ret

Condition_And:
    ; AND compound condition
    ; Data format: DB subcondition_count, then N subconditions inline
    ; Evaluates all subconditions; returns true only if ALL are true
    ; Input: B = Entity Index, HL = Params (points to count byte)
    ; Output: A = 1 (all true) or 0 (any false), HL = past all subcondition data
    ld c, (hl)              ; C = subcondition count
    inc hl
    ld d, 1                 ; D = result accumulator (1 = all true so far)

.and_loop:
    ld a, c
    or a
    jr z, .and_done         ; No more subconditions

    push bc                 ; Save count (C) and entity index (implicitly)
    push de                 ; Save result accumulator (D)

    ld a, b                 ; A = Entity Index
    call SM_EvaluateCondition ; A = subcondition result, HL advanced

    pop de                  ; Restore result accumulator
    and d                   ; Combine: D = D AND result
    ld d, a

    pop bc                  ; Restore count and entity index
    dec c
    jr .and_loop

.and_done:
    ld a, d                 ; A = AND result
    ret

; [Condition_Or stripped - not used]

; [Condition_Xor stripped - not used]

; [Condition_Not stripped - not used]

SM_MatchDirection:
    ld e, a
    cp d
    jp z, .smd_match_yes    ; exact match always passes

    ld a, d
    cp 1                    ; UP
    jp nz, .smd_not_up
    ld a, e
    cp 2                    ; UP+RIGHT
    jr z, .smd_check_up
    cp 8                    ; UP+LEFT
    jp nz, .smd_match_no
.smd_check_up:
    push hl
    push de
    ld hl, entity_dir_mask
    ld d, 0
    ld e, b
    add hl, de
    ld a, (hl)
    pop de
    pop hl
    and DIR_ALLOW_UP
    jp nz, .smd_match_yes
    jp .smd_match_no

.smd_not_up:
    cp 5                    ; DOWN
    jp nz, .smd_not_down
    ld a, e
    cp 4                    ; DOWN+RIGHT
    jr z, .smd_check_down
    cp 6                    ; DOWN+LEFT
    jp nz, .smd_match_no
.smd_check_down:
    push hl
    push de
    ld hl, entity_dir_mask
    ld d, 0
    ld e, b
    add hl, de
    ld a, (hl)
    pop de
    pop hl
    and DIR_ALLOW_DOWN
    jp nz, .smd_match_yes
    jp .smd_match_no

.smd_not_down:
    cp 7                    ; LEFT
    jp nz, .smd_not_left
    ld a, e
    cp 6                    ; DOWN+LEFT
    jr z, .smd_check_left
    cp 8                    ; UP+LEFT
    jp nz, .smd_match_no
.smd_check_left:
    push hl
    push de
    ld hl, entity_dir_mask
    ld d, 0
    ld e, b
    add hl, de
    ld a, (hl)
    pop de
    pop hl
    and DIR_ALLOW_LEFT
    jp nz, .smd_match_yes
    jp .smd_match_no

.smd_not_left:
    cp 3                    ; RIGHT
    jp nz, .smd_match_no
    ld a, e
    cp 2                    ; UP+RIGHT
    jr z, .smd_check_right
    cp 4                    ; DOWN+RIGHT
    jp nz, .smd_match_no
.smd_check_right:
    push hl
    push de
    ld hl, entity_dir_mask
    ld d, 0
    ld e, b
    add hl, de
    ld a, (hl)
    pop de
    pop hl
    and DIR_ALLOW_RIGHT
    jp nz, .smd_match_yes

.smd_match_no:
    xor a
    ret

.smd_match_yes:
    ld a, 1
    ret

; ------------------------------------------------------------------
; HELPER: Deduce movement direction from entity velocity
; Input: B = Entity Index
; Output: A = direction key id (1/3/5/7) or 0 if idle
; ------------------------------------------------------------------
; [SM_DeduceDirectionFromVelocity stripped - not used]

; [SM_TestMoveDirection stripped - not used]

Condition_KeyPressed:
    ; Check if input is disabled for this entity
    push hl
    ld c, b
    ld b, 0
    ld hl, entity_input_disabled
    add hl, bc
    ld a, (hl)
    pop hl
    ld b, c             ; Restore B = entity index
    or a
    jr z, .sm_input_enabled
    xor a               ; A = 0 (key not pressed, input disabled)
    inc hl              ; Skip keyId param
    ret
.sm_input_enabled:
    ; Edge keydown: active now and inactive previous frame
    ; Params: Key ID (1=Up, 5=Down, 7=Left, 3=Right, 9=Fire)
    ld d, (hl)
    inc hl

    ld a, d
    cp 9
    jr z, .ckp_fire

    ; Directional edge: current active, previous inactive
    ld a, (input_state)
    call SM_MatchDirection
    or a
    jr z, .ckp_not_pressed

    ld a, (prev_input_state)
    call SM_MatchDirection
    or a
    jr nz, .ckp_not_pressed

    ld a, 1
    ret

.ckp_fire:
    ld a, (input_btn_curr)
    and INPUT_BTN_FIRE
    jr z, .ckp_not_pressed
    ld a, (input_btn_prev)
    and INPUT_BTN_FIRE
    jr nz, .ckp_not_pressed
    ld a, 1
    ret

.ckp_not_pressed:
    xor a
    ret

Condition_KeyReleased:
    ; Edge keyup: inactive now and active previous frame
    ; Params: Key ID (1=Up, 5=Down, 7=Left, 3=Right, 9=Fire)
    ld d, (hl)
    inc hl

    ld a, d
    cp 9
    jr z, .ckr_fire

    ; Directional edge: current inactive, previous active
    ld a, (input_state)
    call SM_MatchDirection
    or a
    jr nz, .ckr_not_released

    ld a, (prev_input_state)
    call SM_MatchDirection
    or a
    jr z, .ckr_not_released

    ld a, 1
    ret

.ckr_fire:
    ld a, (input_btn_curr)
    and INPUT_BTN_FIRE
    jr nz, .ckr_not_released
    ld a, (input_btn_prev)
    and INPUT_BTN_FIRE
    jr z, .ckr_not_released
    ld a, 1
    ret

.ckr_not_released:
    xor a
    ret

; [Condition_TimeOut stripped - not used]

; [Condition_CanMove stripped - not used]

; [Condition_HasCollision stripped - not used]

; [Condition_PathClear stripped - not used]

; [Condition_OnWallCollision stripped - not used]

; [Condition_DeadlyTile stripped - not used]

; [Condition_AnimComplete stripped - not used]

; [Condition_KeyAndMove stripped - not used]

Condition_VariableCompare:
    ; Params: VarID (1 byte), Operator (1 byte), CompareSource (1 byte), ValueOrVarID (1 byte)
    ; CompareSource: 0 = constant byte, 1 = variable ID
    ; Input: B = Entity Index, HL = Params Ptr
    ; Output: A = 1 (true) or 0 (false), HL = Updated Ptr
    ; Supports entity variables (ID 0-5) and global variables (ID 6+)

    ld a, (hl)              ; A = Variable ID
    inc hl
    ld c, (hl)              ; C = Operator ID
    inc hl
    ld d, (hl)              ; D = CompareSource
    inc hl
    ld e, (hl)              ; E = Compare Value or Variable ID
    inc hl

    push hl                 ; Save updated params ptr
    push bc                 ; Save Operator and Entity Index
    push de                 ; Save CompareSource/ValueOrVarID

    call .load_variable_value
    ld d, e                 ; D = left value

    pop hl                  ; H = CompareSource, L = Compare Value / VarID
    ld a, h
    or a
    jr z, .compare_constant

    ld a, l                 ; Resolve right-side variable
    call .load_variable_value
    jr .do_compare

.compare_constant:
    ld e, l                 ; E = right constant value

.do_compare:
    pop bc                  ; C = Operator ID, B = Entity Index (restore)
    pop hl                  ; HL = Updated Params Ptr
    
    ; Now: D = Left Value, E = Right Value, C = Operator
    ; Perform comparison based on operator
    ld a, c                 ; A = Operator ID
    
    cp 0                    ; == operator
    jr z, .op_equals
    cp 1                    ; != operator
    jr z, .op_not_equals
    cp 2                    ; > operator
    jr z, .op_greater
    cp 3                    ; < operator
    jr z, .op_less
    cp 4                    ; >= operator
    jr z, .op_greater_equal
    cp 5                    ; <= operator
    jr z, .op_less_equal
    
    ; Invalid operator, return false
    ld a, 0
    ret

.op_equals:
    ld a, d
    cp e
    jr z, .return_true
    jr .return_false

.op_not_equals:
    ld a, d
    cp e
    jr nz, .return_true
    jr .return_false

.op_greater:
    ld a, d
    cp e
    jr z, .return_false
    jr nc, .return_true
    jr .return_false

.op_less:
    ld a, d
    cp e
    jr c, .return_true
    jr .return_false

.op_greater_equal:
    ld a, d
    cp e
    jr nc, .return_true
    jr .return_false

.op_less_equal:
    ld a, d
    cp e
    jr z, .return_true
    jr c, .return_true
    jr .return_false

.load_variable_value:
    push bc

    cp 6
    jr nc, .load_global_var

    ld c, b
    ld b, 0

    cp 0
    jr z, .load_x
    cp 1
    jr z, .load_y
    cp 2
    jr z, .load_vx
    cp 3
    jr z, .load_vy
    cp 4
    jr z, .load_on_ground

.load_health:
    ld hl, entity_health_current
    add hl, bc
    ld e, (hl)
    jr .load_done

.load_global_var:
    sub 6
    ld l, a
    ld h, 0
    add hl, hl
    ld de, SM_GlobalVarTable
    add hl, de
    ld e, (hl)
    inc hl
    ld d, (hl)
    ld a, (de)
    ld e, a
    jr .load_done

.load_x:
    ld hl, entity_x_pos
    add hl, bc
    ld e, (hl)
    jr .load_done

.load_y:
    ld hl, entity_y_pos
    add hl, bc
    ld e, (hl)
    jr .load_done

.load_vx:
    ld hl, entity_vel_x
    add hl, bc
    ld e, (hl)
    jr .load_done

.load_vy:
    ld hl, entity_vel_y
    add hl, bc
    ld e, (hl)
    jr .load_done

.load_on_ground:
    ld hl, entity_on_ground
    add hl, bc
    ld a, (hl)
    and #01
    ld e, a

.load_done:
    pop bc
    ret

.return_true:
    ld a, 1
    ret

.return_false:
    ld a, 0
    ret
    

; ==================================================================
; GLOBAL VARIABLES TABLE
; ==================================================================
; Maps variable IDs (6+) to their RAM addresses
; ID 6 = gem_count, ID 7 = last_interaction_char, ID 8 = pending, ID 9+ = interaction context, ID 15+ = user globals
SM_GlobalVarTable:
    DW gem_count            ; ID 6: gem_count
    DW last_interaction_char ; ID 7: last_interaction_char
    DW last_interaction_pending ; ID 8: last_interaction_pending
    DW last_interaction_type ; ID 9: last_interaction_type
    DW last_interaction_value ; ID 10: last_interaction_value
    DW last_interaction_target ; ID 11: last_interaction_target
    DW last_interaction_x   ; ID 12: last_interaction_x
    DW last_interaction_y   ; ID 13: last_interaction_y
    DW last_interaction_entity ; ID 14: last_interaction_entity
    DW global_var_score            ; ID 15: Score
    DW global_var_time_remaining            ; ID 16: TimeRemaining
    DW global_var_buttons_activated            ; ID 17: buttons_activated
    DW global_var_buttons_reward_granted            ; ID 18: buttons_reward_granted

; Global variable width flags: 1 = word, 0 = byte
SM_GlobalVarWordTable:
    DB 0 ; ID 6: gem_count
    DB 0 ; ID 7: last_interaction_char
    DB 0 ; ID 8: last_interaction_pending
    DB 0 ; ID 9: last_interaction_type
    DB 0 ; ID 10: last_interaction_value
    DB 0 ; ID 11: last_interaction_target
